function farthestFromShore(grid: number[][]): number {
  const n = grid.length, land: [number, number][] = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (grid[r][c] === 1) land.push([r, c]);
  if (land.length === 0 || land.length === n * n) return -1;
  let best = 0;
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] === 1) continue;
    let near = Infinity;
    for (const [lr, lc] of land) near = Math.min(near, Math.abs(r - lr) + Math.abs(c - lc));
    best = Math.max(best, near);
  }
  return best;
}

