function farthestFromShore(grid: number[][]): number {
  const n = grid.length;
  const seen = grid.map(row => row.slice());
  let queue: [number, number][] = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (seen[r][c] === 1) queue.push([r, c]);
  if (queue.length === 0 || queue.length === n * n) return -1;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let rings = -1;
  while (queue.length) {
    rings++;
    const next: [number, number][] = [];
    for (const [r, c] of queue) {
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && seen[nr][nc] === 0) {
          seen[nr][nc] = 1; // mark on push
          next.push([nr, nc]);
        }
      }
    }
    queue = next;
  }
  return rings;
}

