    def farthestFromShore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        seen = [row[:] for row in grid]
        q = deque((r, c) for r in range(n) for c in range(n) if seen[r][c] == 1)
        if not q or len(q) == n * n:
            return -1
        rings = -1
        while q:
            rings += 1
            for _ in range(len(q)):
                r, c = q.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < n and 0 <= nc < n and seen[nr][nc] == 0:
                        seen[nr][nc] = 1  # mark on push
                        q.append((nr, nc))
        return rings

