function farthestFromShore(grid: number[][]): number {
  const n = grid.length, BIG = 1e9;
  const d = grid.map(row => row.map(v => (v === 1 ? 0 : BIG)));
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
    if (r > 0) d[r][c] = Math.min(d[r][c], d[r - 1][c] + 1);
    if (c > 0) d[r][c] = Math.min(d[r][c], d[r][c - 1] + 1);
  }
  let best = 0;
  for (let r = n - 1; r >= 0; r--) for (let c = n - 1; c >= 0; c--) {
    if (r < n - 1) d[r][c] = Math.min(d[r][c], d[r + 1][c] + 1);
    if (c < n - 1) d[r][c] = Math.min(d[r][c], d[r][c + 1] + 1);
    best = Math.max(best, d[r][c]);
  }
  return best === 0 || best >= BIG ? -1 : best;
}

